impl<'a, R: CommandRunner, D: DependencyResolver> Workspace<'a, R, D> {
    /// Fails if the walk dropped a manifest it could not resolve, because a release planned from the rest would be
    /// smaller than the repository.
    ///
    /// # Errors
    ///
    /// [`GraphError::IncompleteWorkspace`] naming every unresolved manifest.
    pub fn require_complete(&self) -> Result<(), GraphError> {
        // One manifest can fail in several stages of the walk; name it once.
        let mut seen = BTreeSet::new();
        let unresolved: Vec<String> = self
            .graph
            .diagnostics()
            .iter()
            .filter(|diagnostic| diagnostic.code == callisto_model::DiagnosticCode::ManifestUnresolved)
            .filter(|diagnostic| diagnostic.path.as_ref().is_none_or(|path| seen.insert(path.clone())))
            .map(|diagnostic| diagnostic.message.clone())
            .collect();
        if unresolved.is_empty() {
            Ok(())
        } else {
            Err(GraphError::IncompleteWorkspace { unresolved })
        }
    }

    /// Returns the workspace's [`TagIndex`], building it on first access and
    /// reusing the cached result afterwards. See the doc comment on the
    /// `tags` field for why this is deferred rather than built eagerly by
    /// [`Workspace::load`].
    pub fn tags(&self) -> Result<&TagIndex, GraphError> {
        if let Some(existing) = self.tags.get() {
            return Ok(existing);
        }
        let built = TagIndex::build(self.git_access(), &self.graph, &self.identity, &self.config)?;
        // `OnceCell::set` only fails if another write already raced it in;
        // `Workspace` is only ever accessed through `&self` here (never
        // shared across threads -- `R`/`D` carry no such bound), so the
        // `get()` check above already ruled that out. Fall back to `get()`
        // either way rather than trusting the `set` call's own return value,
        // so this stays correct even if that assumption ever changes.
        self.tags.set(built).ok();
        Ok(self
            .tags
            .get()
            .expect("tags was just set above, or already set by a prior call"))
    }

    /// Returns the workspace's shared [`GitAccess`], rooted at the workspace
    /// root and running `git` through the workspace's runner.
    pub fn git_access(&self) -> &GitAccess<'a> {
        self.git.get_or_init(|| GitAccess::new(&self.root, self.runner))
    }

    pub fn base_versions(&self) -> Result<BTreeMap<PackageId, Version>, GraphError> {
        let ctx = callisto_manifests::OpenContext::for_workspace_root(&self.root)?;

        let mut versions = BTreeMap::new();
        for pkg in self.graph.packages() {
            let mut found_version = None;
            for decl in &pkg.manifests {
                if decl.role == callisto_model::ManifestRole::Canonical {
                    let handle = manifest_cache::open_cached(&self.manifest_cache, decl, &ctx)?;
                    let v = handle.current_version()?;
                    found_version = Some(v);
                    break;
                }
            }
            if let Some(version) = found_version {
                versions.insert(pkg.id.clone(), version);
            } else {
                return Err(GraphError::Manifest(callisto_model::ManifestError::MissingField {
                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                    field: "version",
                }));
            }
        }
    }
    set.into_iter().collect()
}

/// Whether each of `packages` changed since its last tag: a non-merge commit
/// in `tag..HEAD` touched one of its paths, or its tracked files differ from
/// the tag. An untagged package counts as changed.
///
/// One `git rev-parse` for every tag, then per distinct tag commit one `git
/// log` and at most one `git diff`, however many packages share that commit.
pub fn changed_since_last_tag(
    packages: &[&Package],
    tags: &TagIndex,
    git: &GitAccess<'_>,
) -> Result<BTreeMap<PackageId, bool>, GraphError> {
    let mut changed = BTreeMap::new();
    let mut tagged = Vec::new();
    for pkg in packages {
        match tags.last_tag(&pkg.id) {
            // Fully qualified so a tag name can never be misread as a flag.
            Some(last) => tagged.push((*pkg, format!("refs/tags/{}", last.name.as_str()))),
            None => {
                changed.insert(pkg.id.clone(), true);
            }
        }
    }
    if tagged.is_empty() {
        return Ok(changed);
    }

    let refs: Vec<String> = tagged.iter().map(|(_, r)| r.clone()).collect();
    let keys: Vec<String> = match git.resolve_commits(&refs)? {
        Some(shas) => shas.iter().map(|sha| sha.as_str().to_string()).collect(),
        None => refs,
    };
    let mut groups: BTreeMap<String, Vec<&Package>> = BTreeMap::new();
    for ((pkg, _), key) in tagged.into_iter().zip(keys) {
        groups.entry(key).or_default().push(pkg);
    }

    for (since, members) in groups {
        // A failed walk only skips the cheap check in favor of the exact diff.
        let committed = match git.paths_changed_since(&since) {
            Err(VcsError::Command(e)) => return Err(VcsError::Command(e).into()),
            result => result.unwrap_or_default(),
        };
        let mut differing: Option<Option<Vec<PathBuf>>> = None;
        for pkg in members {
            let specs = package_paths(pkg);
            let mut is_changed = touches(&committed, &specs);
            if !is_changed {
                subject: subject.clone(),
            }),
            None => Some(ChangeSource::Changeset {
                filename: String::new(),
                summary: format!("Inferred version bump ({commits} commit(s))"),
            }),
        },
        _ => None,
    }
}

pub fn plan_version<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
    ws: &Workspace<'_, R, D>,
    inference: &I,
    opts: &VersionOptions,
) -> Result<VersionPlan, GraphError> {
    let base_versions = ws.base_versions()?;
    let tags = ws.tags()?;

    let pre_path = ws.root.join(ws.config.pre_json_path());
    let pre_text = callisto_model::strict_fs::read_optional(&pre_path)
        .map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
    let (pre_state, pre_json_original_text) = if let Some(text) = pre_text {
        let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
        let state = ws.resolve_pre_state_from_json(state, &text)?;
        (Some(state), Some(text))
    } else {
        (None, None)
    };

    let mut agg = aggregate(
        &ws.graph,
        &ws.identity,
        &ws.config,
        ws.git_access(),
        tags,
        &base_versions,
        pre_state.as_ref(),
        inference,
    )?;

    // For PreMode::Exit, inject a synthetic Patch severity for every package
    // that is currently at a pre-release version. This triggers bump_target
    // (which in Exit mode calls versioning.bump on the pre-release, stripping
    // the tag and finalizing to stable) even when no pending changeset files
    // exist on disk — they were consumed and deleted during the pre-release phase
    // and their stems recorded in pre.json.
    if let Some(ref pre) = pre_state {
        if pre.mode == callisto_model::format::PreMode::Exit {
            for (id, ver) in &base_versions {
                if ver.is_prerelease() {
                    agg.severities.entry(id.clone()).or_insert(Severity::Patch);
                    agg.reasons
                        .entry(id.clone())
                        .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
                }
            }
        }
    }

    let input = CascadeInput {
        graph: &ws.graph,
        groups: &ws.config.groups,
        cfg: &ws.config.cascade,
        seed: &agg.severities,
        reasons: &agg.reasons,
        named_by: &agg.named_by,
        base: &base_versions,
        pre: pre_state.as_ref(),
        tags,
        identity: &ws.identity,
    };

    let napi = crate::napi::NapiTargetsIndex::load(&ws.config.groups, &ws.root, &ws.graph)?;
    let group_check =
        crate::groups::pre_mutation_checks(&ws.graph, &ws.config.groups, &base_versions, tags, &napi, &ws.root)?;

    let outcome = run_cascade(input)?;

    let mut bumps = Vec::new();
    let mut changelog_writes = Vec::new();

toolUseResult.stdout:
            runner,
            manifest_cache,
            identity,
        })
    }
}

